import Foundation

/// What a term means in its sentence, in the learner's native language (SPEC C3).
///
/// Generated by an AI provider, validated, then stored with the word so it never needs to be
/// generated again unless the learner asks.
public struct WordInsight: Codable, Hashable, Sendable {
    /// The term as captured, e.g. "cookies".
    public var term: String
    /// Dictionary form, e.g. "cookie". Falls back to the term when no lemma is known.
    public var lemma: String
    public var partOfSpeech: PartOfSpeech?
    /// The language of the term.
    public var language: LanguageCode
    /// The language the explanation is written in.
    public var nativeLanguage: LanguageCode
    /// The sentence the term came from, if any.
    public var context: String?
    /// The native-language equivalent for this sense, 1–4 words.
    public var translation: String
    /// A short native-language definition of this sense.
    public var meaning: String
    /// The sense in English; quiz and podcast prompts use it to keep the same meaning.
    public var englishGloss: String?
    /// For example "der Schlüssel, die Schlüssel". Only cloud models provide it reliably.
    public var grammarNote: String?
    public var examples: [UsageExample]
    public var otherMeanings: [String]
    public var source: InsightSource
    public var createdAt: Date

    public init(
        term: String,
        lemma: String,
        partOfSpeech: PartOfSpeech? = nil,
        language: LanguageCode,
        nativeLanguage: LanguageCode,
        context: String? = nil,
        translation: String,
        meaning: String,
        englishGloss: String? = nil,
        grammarNote: String? = nil,
        examples: [UsageExample] = [],
        otherMeanings: [String] = [],
        source: InsightSource,
        createdAt: Date = Date()
    ) {
        self.term = term
        self.lemma = lemma
        self.partOfSpeech = partOfSpeech
        self.language = language
        self.nativeLanguage = nativeLanguage
        self.context = context
        self.translation = translation
        self.meaning = meaning
        self.englishGloss = englishGloss
        self.grammarNote = grammarNote
        self.examples = examples
        self.otherMeanings = otherMeanings
        self.source = source
        self.createdAt = createdAt
    }
}

/// An example sentence in the term's language with its native-language translation.
public struct UsageExample: Codable, Hashable, Sendable {
    public var sentence: String
    public var translation: String

    public init(sentence: String, translation: String) {
        self.sentence = sentence
        self.translation = translation
    }
}

/// Which provider and model produced an insight, for display and for regenerating with another one.
public struct InsightSource: Codable, Hashable, Sendable {
    public var providerID: String
    public var modelID: String?

    public init(providerID: String, modelID: String? = nil) {
        self.providerID = providerID
        self.modelID = modelID
    }
}
